{
  "observed_defect": "The current sculpt_path edit creates a lateral displacement that extends beyond the sector boundary, violating the geography contract. The relief is not properly sculpted with a vertical gully or crest, and the 20m radius is too large for the sector, causing the edge to be cut off.",
  "design_intent": "To create a physically sculpted Breach edge in the northeast, with a broad asymmetric gully and a weathered crest, using a vertical relief that is fully contained within the source sector. The relief must be created with a vertical displacement that exceeds 1m and is within the 20m radius limit, ensuring the edge is not cut off and the relief is coherent with the existing terrain.",
  "asset_decision": "REUSE",
  "reason_for_new_geometry": "The current sculpt_path edit is invalid as it extends beyond the sector boundary. A new sculpt_path is required with a vertical relief that is fully contained within the sector, using the original knots and radii from the source geometry.",
  "expected_visual_difference": "The Breach edge will be sculpted with a vertical relief, creating a broad asymmetric gully and a weathered crest that improves the relief of the terrain without flattening the player city parcel. The relief will be fully contained within the sector, ensuring the edge is not cut off.",
  "mobile_risks": "The new sculpt_path edit will have a mobile cost of 1-2 operations, which are minimal and do not require additional resources. The edit will be performed using the existing source geometry, and the resulting mesh will be fully contained within the sector, ensuring the edge is not cut off. The mobile rendering cost is minimal and does not require additional resources.",
  "planned_actions": [
    {
      "id": "/ZoneOne/continuous_prairie",
      "type": "sculpt_path",
      "target": "ZoneOne continuous prairie source",
      "rationale": "The sculpt_path edit will create a vertical relief with a broad asymmetric gully and a weathered crest, using the original knots and radii from the source geometry. The relief will be fully contained within the sector, ensuring the edge is not cut off. The edit will be performed using the existing source geometry, and the resulting mesh will be fully contained within the sector, ensuring the edge is not cut off.",
      "parameters": {
        "knots": [
          {
            "center": [-50.0, 50.0, 0.0],
            "delta": [0.0, 0.0, -1.0],
            "radius": 10.0
          },
          {
            "center": [60.0, 50.0, 0.0],
            "delta": [0.0, 0.0, -1.0],
            "radius": 10.0
          }
        ]
      }
    }
  ]
}
